      "output": "(()=>{\nconst F=window.F,TH=F.THREE,S=F.SHEET,P=S.palette,L=S.look,NL=L.node,FL=NL.flash;\nconst M=(S.modules.find(m=>m.id==='cave')||{scenes:[]}).scenes;\nconst C=c=>new TH.Color(c);\nconst ND=S.nodes.filter(n=>n.scene==='cave');\nconst fo=(L.fog||{}).cave;\nconst bg=C(P.groundCave||P.ground),fog=fo?new TH.Fog(C(fo.color),fo.near,fo.far):null;\nconst dsp=(g,amp)=>{const p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i),a=Math.atan2(z,x),k=1+amp*(Math.sin(a*3+y*.7)*.6+Math.sin(a*7-y*1.3)*.3+Math.sin(a*11+y*2.1)*.15);p.setXYZ(i,x*k,y,z*k)}g.computeVertexNormals();return g};\nconst stone=()=>new TH.MeshStandardMaterial({color:C(P.stone),roughness:.92,metalness:0,flatShading:true});\nconst slab=()=>{const[w,h,d]=NL.size,r=NL.cornerRadius,b=.03,s=new TH.Shape(),x=w/2,z=d/2;\ns.moveTo(-x+r,-z);s.lineTo(x-r,-z);s.quadraticCurveTo(x,-z,x,-z+r);s.lineTo(x,z-r);s.quadraticCurveTo(x,z,x-r,z);s.lineTo(-x+r,z);s.quadraticCurveTo(-x,z,-x,z-r);s.lineTo(-x,-z+r);s.quadraticCurveTo(-x,-z,-x+r,-z);\nconst g=new TH.ExtrudeGeometry(s,{depth:h-2*b,bevelEnabled:true,bevelThickness:b,bevelSize:b-.005,bevelSegments:2,curveSegments:3});\ng.rotateX(Math.PI/2);g.translate(0,h/2-b,0);g.computeBoundingBox();const bb=g.boundingBox;g.translate(0,-bb.max.y,0);return g};\nconst lit=n=>S.cues.filter(c=>c.node===n.id&&c.scene==='cave').map(c=>c.t).sort((a,b)=>a-b);\nconst st=[];\nconst setup=root=>{\nconst sg=slab(),m4=new TH.Matrix4(),q=new TH.Quaternion(),v=new TH.Vector3(),sc=new TH.Vector3(1,1,1),Y=new TH.Vector3(0,1,0);\nconst sd=NL.strip,pr=NL.ports,h=NL.size[1],d=NL.size[2];\nconst strip=new TH.InstancedMesh(new TH.BoxGeometry(NL.size[0]-.2,sd.height,sd.depth),new TH.MeshStandardMaterial({color:C(P.slateStrip),roughness:NL.roughness,metalness:NL.metalness}),ND.length);\nconst port=new TH.InstancedMesh(new TH.SphereGeometry(pr.radius,10,6),new TH.MeshStandardMaterial({color:C(P.port),roughness:.4,metalness:.3}),ND.length*pr.x.length);\nlet pi=0;\nND.forEach((n,i)=>{const mt=new TH.MeshStandardMaterial({color:C(NL.unlit||P.slate),roughness:NL.roughness,metalness:NL.metalness,emissive:C(P.amber),emissiveIntensity:0});\nconst me=new TH.Mesh(sg,mt);me.position.set(n.top[0],n.top[1],n.top[2]);me.rotation.y=n.rotY;root.add(me);\nq.setFromAxisAngle(Y,n.rotY);const o=new TH.Vector3(0,sd.height/2,-d/2+sd.depth/2+.02).applyQuaternion(q);\nv.set(n.top[0]+o.x,n.top[1]+o.y,n.top[2]+o.z);m4.compose(v,q,sc);strip.setMatrixAt(i,m4);\npr.x.forEach(px=>{const o2=new TH.Vector3(px,-h/2,0).applyQuaternion(q);v.set(n.top[0]+o2.x,n.top[1]+o2.y,n.top[2]+o2.z);m4.compose(v,q,sc);port.setMatrixAt(pi++,m4)});\nst.push({m:mt,c:lit(n)})});\nroot.add(strip,port);\nconst ys=ND.map(n=>n.top[1]),y0=Math.max(...ys)+4,y1=Math.min(...ys)-4.4,hh=y0-y1,yc=(y0+y1)/2;\nconst wall=new TH.Mesh(dsp(new TH.CylinderGeometry(12.5,13,hh+6,22,12,true),.12),stone());wall.material.side=TH.BackSide;wall.position.y=yc;root.add(wall);\nconst col=new TH.Mesh(dsp(new TH.CylinderGeometry(.9,1.25,hh+6,10,14,true),.18),stone());col.position.y=yc;root.add(col);\nconst fl=new TH.Mesh(new TH.CircleGeometry(13,22),stone());fl.rotation.x=-Math.PI/2;fl.position.y=y1;root.add(fl);\nconst R=F.rand(1875),rk=new TH.InstancedMesh(new TH.IcosahedronGeometry(1,0),stone(),54),e=new TH.Euler();\nfor(let i=0;i<54;i++){const a=R()*Math.PI*2,fl2=i<36,r=fl2?11+R()*1.5:4+R()*6,y=fl2?y1+R()*(hh+4):y1+R()*.3,s=fl2?.8+R()*1.4:.3+R()*.6;\ne.set(R()*3,R()*3,R()*3);q.setFromEuler(e);v.set(Math.cos(a)*r,y,Math.sin(a)*r);sc.set(s,s*(.6+R()*.6),s);m4.compose(v,q,sc);rk.setMatrixAt(i,m4)}\nroot.add(rk);\nconst sp=new TH.InstancedMesh(new TH.ConeGeometry(1,1,6),stone(),24);\nfor(let i=0;i<24;i++){const a=R()*Math.PI*2,r=4.5+R()*6,s=.25+R()*.4,hg=.8+R()*1.6;q.identity();v.set(Math.cos(a)*r,y1+hg/2,Math.sin(a)*r);sc.set(s,hg,s);m4.compose(v,q,sc);sp.setMatrixAt(i,m4)}\nroot.add(sp);\nconst cy=ys.reduce((a,b)=>a+b,0)/ys.length;\n(L.lights.cave||[]).forEach(l=>{let o;\nif(l.type==='directional'){o=new TH.DirectionalLight(C(l.color),l.intensity);o.position.set(l.from[0],cy+l.from[1],l.from[2]);o.target.position.set(0,cy,0);root.add(o.target)}\nelse if(l.type==='hemisphere')o=new TH.HemisphereLight(C(l.sky),C(l.ground),l.intensity);\nif(o)root.add(o)});\n};\nconst update=T=>{F.world.background=bg;F.world.fog=fog;\nfor(const s of st){let t=-1;for(const c of s.c)if(c<=T)t=c;\nif(t<0){s.m.color.set(NL.unlit||P.slate);s.m.emissiveIntensity=0}\nelse{s.m.color.set(P.amber);s.m.emissiveIntensity=F.lerp(FL.emissiveIntensity,FL.settleTo,F.ease[FL.ease||'arrive']((T-t)/FL.settleSeconds))}}};\nM.forEach(id=>{const sh=S.shots.find(s=>s.id===id);if(sh)F.scene(id,{start:sh.start,end:sh.end,setup,update})});\nF.test('cave: 19 nodes lit by their cues',()=>{const k=st.filter(s=>s.c.length).length;return{ok:k===ND.length&&k>0,detail:k+'/'+ND.length+' nodes have landing cues'}});\n})();\n",
