      "output": "(()=>{const F=window.F,X=F.THREE,S=F.SHEET,P=S.palette,L=S.look,sh=S.shots.find(s=>s.module==='track');if(!sh)return;\nconst C=c=>new X.Color(c),N=S.nodes.filter(n=>n.scene==='track'),Q=S.cues.filter(c=>c.scene==='track'&&c.node),ns=L.node.size,cr=L.node.cornerRadius,fl=L.node.flash,fg=L.fog.track,st=L.node.strip,po=L.node.ports;\nconst R=N.filter(n=>!n.decoy),a=R[0],b=R[R.length-1],k=(b.top[1]-a.top[1])/(b.top[2]-a.top[2]),fy=z=>a.top[1]+(z-a.top[2])*k,th=-Math.atan(k),D=0.9,ct=Math.cos(th);\nconst z0=a.top[2]+9,z1=b.top[2]-9,zc=(z0+z1)/2,len=(z0-z1)/ct;\nconst bg=C(P.groundTrack),fog=new X.Fog(C(fg.color),fg.near,fg.far),cs=C(P.slate),cg=C(P.green);\nconst rr=(w,h,r)=>{const s=new X.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return s};\nconst M=(c,o)=>new X.MeshStandardMaterial(Object.assign({color:C(c),roughness:L.node.roughness,metalness:L.node.metalness},o||{}));\nlet ms=[];\nconst setup=root=>{const inst=(g,m,l)=>{const im=new X.InstancedMesh(g,m,l.length),o=new X.Object3D();l.forEach((p,i)=>{o.position.set(p[0],p[1],p[2]);o.rotation.set(p[3]||0,p[4]||0,0);o.scale.set(p[5]||1,p[6]||1,p[7]||1);o.updateMatrix();im.setMatrixAt(i,o.matrix)});im.instanceMatrix.needsUpdate=true;im.frustumCulled=false;root.add(im);return im};\nconst dp=ns[1]-2*cr,g=new X.ExtrudeGeometry(rr(ns[0]-2*cr,ns[2]-2*cr,0.04),{depth:dp,bevelEnabled:true,bevelThickness:cr,bevelSize:cr,bevelSegments:2,curveSegments:2});g.rotateX(-Math.PI/2);g.translate(0,-(dp+cr),0);\nms=N.map(n=>{const m=M(P.slate,{emissive:cg.clone(),emissiveIntensity:0}),me=new X.Mesh(g,m);me.position.set(n.top[0],n.top[1],n.top[2]);me.rotation.y=n.rotY||0;root.add(me);return[m,Q.filter(c=>c.node===n.id).map(c=>c.t).sort((u,v)=>u-v)]});\nconst sp=[],pt=[],pl=[];N.forEach(n=>{const[x,y,z]=n.top;sp.push([x,y+st.height/2,z-ns[2]/2+st.depth/2+0.02]);po.x.forEach(px=>pt.push([x+px,y-ns[1]/2,z]));const h=y-ns[1]-(fy(z)-D);pl.push([x,y-ns[1]-h/2,z,0,0,1,h,1])});\ninst(new X.BoxGeometry(ns[0]-0.24,st.height,st.depth),M(P.slateStrip),sp);\ninst(new X.SphereGeometry(po.radius,10,6),M(P.port),pt);\ninst(new X.CylinderGeometry(0.12,0.16,1,8),M(P.slate),pl);\nconst yc=fy(zc)-D-0.06,rb=new X.Mesh(new X.BoxGeometry(5,0.12,len),M(P.groundTrack,{color:C(P.groundTrack).lerp(cs,0.55),roughness:0.85}));rb.position.set(0,yc,zc);rb.rotation.x=th;root.add(rb);\nconst ds=[],kb=[[],[]],ps=[],n0=Math.floor((z0-z1)/1.2);for(let i=0;i<n0;i++){const z=z0-i*1.2,y=fy(z)-D;ds.push([0,y+0.005,z,th,0,0.08,1,0.55]);[-1,1].forEach(s=>kb[i%2].push([s*2.35,y+0.01,z,th,0,0.3,1,1.2]));if(i%2==0)[-1,1].forEach(s=>ps.push([s*2.6,y+0.25,z]))}\ninst(new X.BoxGeometry(1,0.02,1),M(P.slateStrip),ds);\nkb.forEach((l,j)=>inst(new X.BoxGeometry(1,0.04,1),M(j?P.port:P.slateStrip),l));\ninst(new X.CylinderGeometry(0.035,0.035,0.5,6),M(P.port),ps);\n[-1,1].forEach(s=>{const r=new X.Mesh(new X.BoxGeometry(0.07,0.07,len),M(P.port,{metalness:0.4,roughness:0.4}));r.position.set(s*2.6,yc+0.55,zc);r.rotation.x=th;root.add(r)});\nconst rnd=F.rand(2029),hl=[],hc=C(P.groundTrack).lerp(C(P.stone),0.45);for(let i=0;i<46;i++){const s=i%2?1:-1,x=s*(5+rnd()*14),z=z0-rnd()*(z0-z1+12),h=1.5+rnd()*5,w=2+rnd()*4;hl.push([x,fy(z)-D-1.2+h/2,z,0,rnd()*6,w,h,w])}\ninst(new X.ConeGeometry(1,1,6,1),M(P.stone,{color:hc,roughness:0.95,flatShading:true}),hl);\nconst gr=new X.Mesh(new X.PlaneGeometry(60,len+20),M(P.groundTrack,{roughness:1}));gr.rotation.x=th-Math.PI/2;gr.position.set(0,yc-1.3,zc);root.add(gr);\nconst lt=L.lights.track,dl=lt.find(l=>l.type==='directional'),hm=lt.find(l=>l.type==='hemisphere');\nif(dl){const d=new X.DirectionalLight(C(dl.color),dl.intensity);d.target.position.set(0,fy(zc),zc);d.position.set(dl.from[0],fy(zc)+dl.from[1],zc+dl.from[2]);root.add(d,d.target)}\nif(hm)root.add(new X.HemisphereLight(C(hm.sky),C(hm.ground),hm.intensity))};\nconst update=T=>{F.world.background=bg;F.world.fog=fog;ms.forEach(([m,ts])=>{let l=-1;for(const t of ts)if(t<=T+1e-6)l=t;if(l<0){m.emissiveIntensity=0;m.color.copy(cs)}else{m.emissiveIntensity=F.lerp(fl.emissiveIntensity,fl.settleTo,F.ease.arrive((T-l)/fl.settleSeconds));m.color.copy(cs).lerp(cg,0.35)}})};\nF.scene(sh.id,{start:sh.start,end:sh.end,setup,update})})();\n",
