      "output": "(()=>{\nconst F=window.F,S=F.SHEET,P=S.palette,L=S.look,N=L.node,TH=F.THREE;\nconst C=c=>new TH.Color(c),M=o=>new TH.MeshStandardMaterial(o);\nconst ids=S.nodes.filter(n=>n.scene==='stage');\nconst byId={};S.nodes.forEach(n=>byId[n.id]=n);\nconst cues=S.cues.filter(c=>c.scene==='stage'&&c.node).sort((a,b)=>a.t-b.t);\nconst R=L.token.radius,[nw,nh,nd]=N.size,cr=N.cornerRadius;\nconst tp=n=>{const t=byId[n].top;return[t[0],t[1]+R,t[2]]};\nconst tok=T=>{\nlet i=0;while(i<cues.length-1&&cues[i+1].t<=T)i++;\nconst a=cues[i],b=cues[i+1];\nif(!b||T<a.t)return tp(a.node);\nconst p=tp(a.node),q=tp(b.node),d=b.t-a.t,s=T-a.t,h=Math.max(p[1],q[1])+b.arcPeak;\nconst sg=(Math.sqrt(2*(h-p[1]))+Math.sqrt(2*(h-q[1])))/d,g=sg*sg,ta=Math.sqrt(2*(h-p[1]))/sg,k=s/d;\nreturn[F.lerp(p[0],q[0],k),h-g/2*(s-ta)*(s-ta),F.lerp(p[2],q[2],k)]};\nconst lit=(id,T)=>{let t=null;for(const c of cues)if(c.node===id&&c.t<=T)t=c.t;\nif(t===null)return 0;const f=N.flash;return F.lerp(f.emissiveIntensity,f.settleTo,F.ease[f.ease](F.clamp((T-t)/f.settleSeconds,0,1)))};\nconst slab=()=>{const w=nw/2-cr,d=nd/2-cr,r=0.04,s=new TH.Shape();\ns.moveTo(-w+r,-d);s.lineTo(w-r,-d);s.quadraticCurveTo(w,-d,w,-d+r);s.lineTo(w,d-r);s.quadraticCurveTo(w,d,w-r,d);\ns.lineTo(-w+r,d);s.quadraticCurveTo(-w,d,-w,d-r);s.lineTo(-w,-d+r);s.quadraticCurveTo(-w,-d,-w+r,-d);\nconst g=new TH.ExtrudeGeometry(s,{depth:Math.max(0.01,nh-2*cr),bevelEnabled:true,bevelThickness:cr,bevelSize:cr,bevelSegments:2,curveSegments:3});\ng.rotateX(-Math.PI/2);g.center();g.translate(0,-nh/2,0);return g};\nconst fl=L.fog.stage,bg=C(P.groundStage),fog=new TH.Fog(C(fl.color),fl.near,fl.far);\nlet st=null;\nconst setup=root=>{\nconst gs=slab(),blue=C(P.blue),nm=[];\nconst sg=new TH.BoxGeometry(nw-2*cr,N.strip.height,N.strip.depth),pg=new TH.SphereGeometry(N.ports.radius,10,6);\nconst sm=new TH.InstancedMesh(sg,M({color:C(P.slateStrip),roughness:N.roughness,metalness:N.metalness}),ids.length);\nconst pm=new TH.InstancedMesh(pg,M({color:C(P.port),roughness:0.4,metalness:0.3}),ids.length*2);\nconst o=new TH.Object3D();\nids.forEach((n,i)=>{\nconst m=new TH.Mesh(gs,M({color:C(N.unlit),roughness:N.roughness,metalness:N.metalness,emissive:blue,emissiveIntensity:0}));\nm.position.set(...n.top);m.rotation.y=n.rotY||0;root.add(m);nm.push({n,m});\no.rotation.set(0,n.rotY||0,0);o.position.set(n.top[0],n.top[1]+N.strip.height/2,n.top[2]-nd/2+N.strip.depth/2+cr/2);o.updateMatrix();sm.setMatrixAt(i,o.matrix);\nN.ports.x.forEach((x,j)=>{o.position.set(n.top[0]+x,n.top[1]-nh/2,n.top[2]);o.updateMatrix();pm.setMatrixAt(i*2+j,o.matrix)})});\nroot.add(sm,pm);\nconst fm=M({color:C(P.groundStage).multiplyScalar(2.2),roughness:0.35,metalness:0.2});\nconst fg=new TH.PlaneGeometry(16,44,1,1);fg.rotateX(-Math.PI/2);\nconst fls=new TH.Mesh(fg,fm);fls.rotation.x=-Math.atan(0.375);fls.position.set(0,-24-13*0.375-7,-49);root.add(fls);\nconst cg=new TH.PlaneGeometry(1,1,64,1),pa=cg.attributes.position;\nfor(let i=0;i<pa.count;i++){const x=pa.getX(i);pa.setZ(i,Math.sin(x*Math.PI*24)*0.025)}\ncg.computeVertexNormals();\nconst cm=M({color:C(P.groundStage).multiplyScalar(4.5).offsetHSL(0,0.25,0),roughness:0.85,metalness:0,side:TH.DoubleSide});\n[[-6,Math.PI/2,46,-48,-30],[6,-Math.PI/2,46,-48,-30],[0,0,14,-67,-36]].forEach(([x,ry,w,z,y])=>{\nconst c=new TH.Mesh(cg,cm);c.scale.set(w,24,1);c.rotation.y=ry;c.position.set(x,y,z);root.add(c)});\nconst vg=new TH.BoxGeometry(14,0.6,0.6),vm=M({color:C(P.groundStage).multiplyScalar(6),roughness:0.6});\nconst va=new TH.Mesh(vg,vm);va.position.set(0,-22,-36);root.add(va);\nconst rng=F.rand(303),fc=24,fq=new TH.InstancedMesh(new TH.SphereGeometry(0.07,8,4),M({color:0,emissive:C(P.spot),emissiveIntensity:0.6,roughness:0.5}),fc);\nfor(let i=0;i<fc;i++){const z=-34-i*1.4,s=0.8+rng()*0.4;o.rotation.set(0,0,0);o.scale.set(s,s,s);o.position.set(i%2?5.2:-5.2,0,z);o.position.y=-24+(z+36)*0.375-6.9;o.updateMatrix();fq.setMatrixAt(i,o.matrix)}\no.scale.set(1,1,1);root.add(fq);\nconst sp=L.lights.stage.map(l=>{const s=new TH.SpotLight(C(l.color),l.intensity,0,l.angle,l.penumbra,2);root.add(s,s.target);\nconst cn=new TH.Mesh(new TH.ConeGeometry(1,1,24,1,true),M({color:0,emissive:C(l.color),emissiveIntensity:0.5,transparent:true,opacity:0.05,depthWrite:false,side:TH.DoubleSide}));\ncn.geometry.translate(0,-0.5,0);root.add(cn);return{l,s,cn}});\nst={nm,sp}};\nconst up=new TH.Vector3(0,-1,0),v=new TH.Vector3(),w=new TH.Vector3();\nconst update=(T)=>{\nif(F.world){F.world.background=bg;F.world.fog=fog}\nconst blue=C(P.blue);\nst.nm.forEach(({n,m})=>{const e=n.decoy?0:lit(n.id,T);m.material.emissiveIntensity=e;\nm.material.color.set(e>0?(n.id==='review'?P.blue:N.unlit):N.unlit);if(e>0&&n.id!=='review')m.material.color.lerp(blue,0.35);\nm.position.set(...n.top)});\nconst p=tok(T);\nst.sp.forEach(({l,s,cn})=>{s.position.set(p[0]+l.from[0],p[1]+l.from[1],p[2]+l.from[2]);s.target.position.set(...p);s.target.updateMatrixWorld();\nv.set(...p).sub(s.position);const d=v.length();cn.position.copy(s.position);cn.scale.set(Math.tan(l.angle)*d,d,Math.tan(l.angle)*d);\ncn.quaternion.setFromUnitVectors(up,w.copy(v).normalize())})};\nfor(const sh of S.shots.filter(s=>s.module==='stage'))F.scene(sh.id,{start:sh.start,end:sh.end,setup,update});\n})();\n",
