      "output": "(()=>{const F=window.F,H3=F.THREE,S=F.SHEET,K=S.look.token,R=K.radius,LT=S.look.lights.token,CM=S.look.camera,N={};\nS.nodes.forEach(n=>N[n.id]=n);\nconst L=S.cues.filter(c=>c.node&&N[c.node]).sort((a,b)=>a.t-b.t).map(c=>({t:c.t,p:N[c.node].top,k:c.arcPeak==null?1.2:c.arcPeak}));\nconst SH=S.shots.slice().sort((a,b)=>a.start-b.start);\nconst shot=T=>{let s=SH[0];for(const x of SH)if(T>=x.start)s=x;return s};\nconst pos=T=>{const n=L.length;let i=0;while(i<n-1&&L[i+1].t<=T)i++;const a=L[i];\nif(T<=L[0].t||i==n-1)return{p:[a.p[0],a.p[1]+R,a.p[2]],d:Math.max(0,T-a.t)};\nconst b=L[i+1],s=F.clamp((T-a.t)/(b.t-a.t),0,1),y0=a.p[1]+R,y1=b.p[1]+R,h=Math.max(y0,y1)+b.k,u=Math.sqrt(h-y0),v=Math.sqrt(h-y1),w=u*(1-s)-v*s;\nreturn{p:[F.lerp(a.p[0],b.p[0],s),h-w*w,F.lerp(a.p[2],b.p[2],s)],d:T-a.t}};\nconst cam=T=>{const sh=shot(T),c=[0,0,0];for(let k=0;k<9;k++){const p=pos(Math.max(sh.start,T-.4*k/8)).p;for(let j=0;j<3;j++)c[j]+=p[j]/9}\nconst o=CM.followOffset;let q;if(sh.module=='cave'){const r=Math.hypot(c[0],c[2])||1;q=[c[0]+c[0]/r*o[2],c[1]+o[1],c[2]+c[2]/r*o[2]]}else q=[c[0]+o[0],c[1]+o[1],c[2]+o[2]];\nreturn{position:q,target:[c[0],c[1]-CM.lookBelowToken,c[2]],fov:CM.fov}};\nF.cam=cam;\nlet m,g;\nF.scene('token',{start:0,end:F.LENGTH,setup(root){g=new H3.Group();\nm=new H3.Mesh(new H3.SphereGeometry(R,32,20),new H3.MeshStandardMaterial({color:K.color,emissive:K.color,emissiveIntensity:K.emissiveIntensity,roughness:.35,metalness:0}));\nconst l=new H3.PointLight(LT.color,LT.intensity,LT.distance,LT.decay);g.add(m,l);root.add(g)},\nupdate(T){const r=pos(T),sq=r.d<K.squashFrames/F.FPS,sy=sq?1-K.squash:1,sx=sq?1+K.squash/2:1;\ng.position.set(r.p[0],r.p[1]-R*(1-sy),r.p[2]);m.scale.set(sx,sy,sx);g.visible=true}});\nF.test('token rests on every landing and camera is finite',()=>{let bad=0;\nfor(const c of L){const p=pos(c.t).p;if(Math.abs(p[0]-c.p[0])+Math.abs(p[1]-c.p[1]-R)+Math.abs(p[2]-c.p[2])>1e-6)bad++}\nfor(let t=0;t<F.LENGTH;t+=.25){const c=cam(t);if(![...c.position,...c.target].every(isFinite))bad++}\nreturn{ok:bad==0&&L.length>0,detail:L.length+' landings, '+bad+' bad'}});\n})();\n",
