      "output": "(()=>{const F=window.F,S=F.SHEET,P=S.palette,Fn=S.fonts,N={};for(const n of S.nodes)N[n.id]=n;\nconst B=S.bubbles,bt=new Set(B.map(b=>b.text)),rv=S.nodes.find(n=>n.title)||{},L=[];\nfor(const s of S.shots){const ws=s.words.filter(w=>!bt.has(w.text)),pa=ws.filter(w=>w.role==='poster').map(w=>w.at);\nfor(const w of ws)L.push({w,k:w.role==='poster'?0:w.text===rv.title?2:w.role==='caption'&&pa.includes(w.at)?1:3})}\nlet V,K,R;\nconst fd=(T,a,u)=>F.ease.arrive(F.win(T,a,.25))*(1-F.ease.leave(F.win(T,u-.25,.25)));\nconst cam=T=>{if(typeof F.cam==='function'){const c=F.cam(T);K.position.set(c.position[0],c.position[1],c.position[2]);K.fov=c.fov||45;K.aspect=F.W/F.H;K.lookAt(c.target[0],c.target[1],c.target[2]);K.updateProjectionMatrix();K.updateMatrixWorld();return K}\nconst c=F.camera;c.updateMatrixWorld();return c};\nconst pj=(C,p,dy)=>{V.set(p[0],p[1]+dy,p[2]).project(C);const b=V.z>1||!isFinite(V.x)||!isFinite(V.y);return b?[F.W/2,F.H*.85]:[(V.x*.5+.5)*F.W,(.5-V.y*.5)*F.H]};\nconst ov=(a,b,g)=>a.x<b.x+b.w+g&&b.x<a.x+a.w+g&&a.y<b.y+b.h+g&&b.y<a.y+a.h+g;\nfunction place(r,Q){const mx=F.W*.06,my=F.H*.06,cl=()=>{r.x=F.clamp(r.x,mx,Math.max(mx,F.W-mx-r.w));r.y=F.clamp(r.y,my,Math.max(my,F.H-my-r.h))},g=F.H*.012;cl();\nfor(let i=0;i<10;i++){const o=Q.find(q=>ov(r,q,g));if(!o)break;const up=o.y-r.h-g;r.y=up>=my?up:o.y+o.h+g;cl();if(i>4)r.x=o.x+o.w+g,cl()}Q.push(r);return r}\nconst mw=(c,t,s,wt,f)=>{c.font=wt+' '+s+'px \"'+f+'\", sans-serif';return c.measureText(t).width};\nfunction rr(c,x,y,w,h,q){c.beginPath();c.moveTo(x+q,y);c.arcTo(x+w,y,x+w,y+h,q);c.arcTo(x+w,y+h,x,y+h,q);c.arcTo(x,y+h,x,y,q);c.arcTo(x,y,x+w,y,q);c.closePath()}\nfunction upd(T,lo,info){const c=(info&&info.ctx2d)||F.overlay.getContext('2d'),W=F.W,H=F.H,Q=[],C=cam(T);\nconst st=[{s:.06,wt:700,f:Fn.display,col:P.ink},{s:.032,wt:500,f:Fn.text,col:P.inkDim},{s:.032,wt:500,f:Fn.text,col:P.ink},{s:.06,wt:700,f:Fn.mark,col:P.ink}];\nconst tl=[];let rl=null;\nfor(const {w,k} of L){if(T<w.at||T>=w.until)continue;const a=fd(T,w.at,w.until);if(a<=0)continue;const y=st[k],s=y.s*H,tw=Math.min(mw(c,w.text,s,y.wt,y.f),W*.86),h=s*1.25;let r;\nif(k===0)r={x:W*.07,y:H*.76,w:tw,h};else if(k===1)r={x:W*.07,y:H*.86,w:tw,h};\nelse if(k===2){const p=pj(C,rv.top,.35);r={x:p[0]-tw/2,y:p[1]-h/2,w:tw,h}}else r={x:W*.94-tw,y:H*.94-h,w:tw,h};\nr=place(r,Q);tl.push([w.text,r,y,s,a,tw])}\nfor(const b of B){if(T<b.at||T>=b.until)continue;const a=fd(T,b.at,b.until),n=N[b.node];if(a<=0||!n)continue;\nconst s=.026*H,wt=n===rv?700:500,tw=Math.min(mw(c,b.text,s,wt,Fn.text),W*.6),px=s*.65,py=s*.45,bw=tw+2*px,bh=s*1.2+2*py,p=pj(C,n.top,.9),e=F.ease.arrive(F.win(T,b.at,.3));\nlet r=place({x:p[0]-bw/2,y:p[1]-bh-s*.5+(1-e)*s*.4,w:bw,h:bh},Q);\nc.save();c.globalAlpha=a;c.fillStyle=P.bubble;rr(c,r.x,r.y,bw,bh,bh*.42);c.fill();\nconst tx=F.clamp(p[0],r.x+bh*.5,r.x+bw-bh*.5),dn=p[1]>r.y+bh/2,ey=dn?r.y+bh:r.y,ty=ey+(dn?1:-1)*s*.55;\nc.beginPath();c.moveTo(tx-s*.35,ey);c.lineTo(tx+s*.35,ey);c.lineTo(F.clamp(p[0],tx-s*.6,tx+s*.6),ty);c.closePath();c.fill();c.restore();\nF.text(c,b.text,r.x+bw/2,r.y+bh/2,{size:s,font:Fn.text,weight:wt,color:P.bubbleInk,align:'center',baseline:'middle',maxWidth:tw+1,alpha:a})}\nfor(const [t,r,y,s,a,tw] of tl)F.text(c,t,r.x,r.y+(r.h-s)/2,{size:s,font:y.f,weight:y.wt,color:y.col,align:'left',baseline:'top',maxWidth:tw+1,alpha:a})}\nF.scene('jokes',{start:0,end:F.LENGTH,setup(root){const T3=F.THREE;V=new T3.Vector3();K=new T3.PerspectiveCamera(45,F.W/F.H||16/9,.1,500);R=new T3.Object3D();R.name='jokes-anchor';root.add(R)},update:upd});\nF.test('jokes: every bubble node exists',()=>{const m=B.filter(b=>!N[b.node]).map(b=>b.node);return{ok:!m.length,detail:m.length?'missing '+m.join(','):B.length+' bubbles on known nodes'}});\n})();\n",
